import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BauHmMU1.js";const d="/websocket-tutorial-site/assets/01-realtime-approaches.Ho23y8MC.svg",g=JSON.parse('{"title":"第 1 章 为什么需要 WebSocket","description":"","frontmatter":{},"headers":[],"relativePath":"01-why-websocket.md","filePath":"01-why-websocket.md","lastUpdated":1792595797000}'),s={name:"01-why-websocket.md"};function n(l,t,c,h,i,b){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="第-1-章-为什么需要-websocket" tabindex="-1">第 1 章 为什么需要 WebSocket <a class="header-anchor" href="#第-1-章-为什么需要-websocket" aria-label="Permalink to &quot;第 1 章 为什么需要 WebSocket&quot;">​</a></h1><h2 id="_1-1-http-的天然局限" tabindex="-1">1.1 HTTP 的天然局限 <a class="header-anchor" href="#_1-1-http-的天然局限" aria-label="Permalink to &quot;1.1 HTTP 的天然局限&quot;">​</a></h2><p>HTTP 协议是**请求-响应（Request-Response）**模型：客户端发起请求，服务端返回响应，然后连接结束（或复用给下一个请求）。这个模型有一个根本性限制——<strong>服务端永远无法主动联系客户端</strong>。</p><p>想象一个聊天室场景：小李发了一条消息，服务端收到了，但小王的浏览器对此一无所知。小王要看到这条消息，只能自己再去问一次服务器：&quot;有新消息吗？&quot;</p><h2 id="_1-2-websocket-出现之前的-土办法" tabindex="-1">1.2 WebSocket 出现之前的&quot;土办法&quot; <a class="header-anchor" href="#_1-2-websocket-出现之前的-土办法" aria-label="Permalink to &quot;1.2 WebSocket 出现之前的&quot;土办法&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>原理</th><th>延迟</th><th>资源浪费</th><th>适用性</th></tr></thead><tbody><tr><td><strong>短轮询（Polling）</strong></td><td>客户端每隔 N 秒发一次 HTTP 请求询问</td><td>高（平均 N/2 秒）</td><td>极高，大量空响应</td><td>已淘汰</td></tr><tr><td><strong>长轮询（Long Polling）</strong></td><td>请求挂起，有数据才返回，返回后立刻再发</td><td>中</td><td>高，反复建立请求</td><td>兼容兜底</td></tr><tr><td><strong>SSE（Server-Sent Events）</strong></td><td>HTTP 长连接，服务端可持续推送文本流</td><td>低</td><td>低</td><td>仅服务端→客户端单向</td></tr><tr><td><strong>WebSocket</strong></td><td>真正的全双工长连接，双方随时互发</td><td>极低</td><td>极低</td><td>双向实时场景首选</td></tr></tbody></table><p><img src="'+d+'" alt="四种实时通信方案时序对比"></p><h2 id="_1-3-websocket-是什么" tabindex="-1">1.3 WebSocket 是什么 <a class="header-anchor" href="#_1-3-websocket-是什么" aria-label="Permalink to &quot;1.3 WebSocket 是什么&quot;">​</a></h2><p>WebSocket 是 <strong>HTML5 标准的一部分</strong>（协议规范见 <a href="https://datatracker.ietf.org/doc/html/rfc6455" target="_blank" rel="noreferrer">RFC 6455</a>，2011 年发布），它在单个 TCP 连接上提供**全双工（full-duplex）**通信通道：</p><ul><li><strong>全双工</strong>：连接建立后，客户端和服务端可以随时互相发送数据，不需要等待对方请求。</li><li><strong>低开销</strong>：握手完成后，数据帧头部最小只有 2 字节（对比 HTTP 每次请求几百字节的头部）。</li><li><strong>低延迟</strong>：消息即时送达，没有轮询间隔。</li><li><strong>持久连接</strong>：一次握手，长期复用，直到一方主动关闭。</li></ul><p>一句话总结：<strong>WebSocket 让浏览器和服务器之间拥有了一条类似&quot;打电话&quot;的通道，而 HTTP 更像&quot;发短信&quot;。</strong></p><hr>',12)])])}const p=e(s,[["render",n]]);export{g as __pageData,p as default};
